//! Loads fixtures/formula_gauntlet.xlsx (generated by
//! scripts/make_formula_gauntlet.py), evaluates it, and scores every
//! self-check cell (column E of each category sheet).
//!
//! The fixture is Excel-compatible: opened in Excel every check reads
//! "OK", so any non-OK row here is an IronCalc compatibility gap. The
//! KNOWN_FAILURES baseline records the accepted gaps by formula text —
//! a new failure (regression) or a newly-passing case (baseline stale)
//! both fail the test loudly.

use ironcalc::base::Model;

/// Formula text (column C input, as IronCalc re-stringifies it) of every
/// case currently expected to score non-OK. Keep sorted per sheet for
/// readable diffs. The "Gaps" sheet is wholesale-expected to fail, so
/// its rows are NOT listed here.
const KNOWN_FAILURES: &[(&str, &str)] = &[
    // (sheet, formula) — populated from a triaged run; see test output.
];

fn is_gap_sheet(name: &str) -> bool {
    name == "Gaps"
}

#[test]
fn formula_gauntlet_matches_baseline() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../fixtures/formula_gauntlet.xlsx"
    );
    let mut model: Model = fastsheet_lib::load_xlsx_with_fallback(path).expect("load gauntlet");
    model.evaluate();

    let sheet_names: Vec<String> = model
        .workbook
        .worksheets
        .iter()
        .map(|ws| ws.name.clone())
        .collect();

    let mut total = 0u32;
    let mut ok = 0u32;
    let mut failures: Vec<(String, String, String, String)> = vec![]; // sheet, addr, formula, verdict
    for (s, name) in sheet_names.iter().enumerate() {
        if name == "Summary" || name == "Data" {
            continue;
        }
        for row in 2..=400 {
            let check = model
                .get_formatted_cell_value(s as u32, row, 5)
                .unwrap_or_default();
            if check.is_empty() {
                continue; // past the last case row
            }
            total += 1;
            if check == "OK" {
                ok += 1;
            } else {
                let formula = model
                    .get_localized_cell_content(s as u32, row, 3)
                    .unwrap_or_default();
                let actual = model
                    .get_formatted_cell_value(s as u32, row, 3)
                    .unwrap_or_default();
                failures.push((name.clone(), format!("C{row}"), formula, actual));
            }
        }
    }

    println!("gauntlet: {ok}/{total} OK");
    for (sheet, addr, formula, actual) in &failures {
        println!("  FAIL {sheet}!{addr}: {formula}  => {actual}");
    }

    // Split failures into gap-sheet (wholesale expected) and the rest.
    let unexpected: Vec<_> = failures
        .iter()
        .filter(|(sheet, _, formula, _)| {
            !is_gap_sheet(sheet)
                && !KNOWN_FAILURES
                    .iter()
                    .any(|(ks, kf)| ks == sheet && kf == formula)
        })
        .collect();

    // Baseline rows that now pass — stale baseline, prune it.
    let fixed: Vec<_> = KNOWN_FAILURES
        .iter()
        .filter(|(ks, kf)| {
            !failures
                .iter()
                .any(|(s, _, f, _)| s == ks && f == kf)
        })
        .collect();

    assert!(
        unexpected.is_empty(),
        "unexpected gauntlet failures (regressions or unrecorded gaps):\n{}",
        unexpected
            .iter()
            .map(|(s, a, f, v)| format!("  {s}!{a}: {f} => {v}"))
            .collect::<Vec<_>>()
            .join("\n")
    );
    assert!(
        fixed.is_empty(),
        "baseline entries now pass — remove from KNOWN_FAILURES:\n{}",
        fixed
            .iter()
            .map(|(s, f)| format!("  {s}: {f}"))
            .collect::<Vec<_>>()
            .join("\n")
    );
}
